export function hasNetwork(c){return c.instrument!=='BidataWind'||c.networkBridge===true;}
export function hasPlotter(c){return hasNetwork(c)&&(c.instrument!=='BidataWind'||c.plotter===true);}
export function enabled(condition,c){const network=hasNetwork(c),dual=c.instrument==='BidataWind';return !condition||({network,plotter:hasPlotter(c),dual,single:!dual,dualDirect:dual&&!network,dualNetwork:dual&&network,gxNetwork:network&&c.vhf==='gx2400',genericGPS:network&&c.vhf!=='gx2400',splitter:c.ais==='external',aisExternal:c.ais==='external',aisNetwork:network&&c.ais==='external',directRF:c.ais!=='external',modern:network&&(c.vhf==='n2k'||c.vhf==='ray'),legacy:network&&c.vhf==='0183',transformer:c.transformer===true,noTransformer:!c.transformer,galvanic:c.galvanic&&!c.transformer,noGalvanic:!c.galvanic&&!c.transformer,gasAlarm:c.gasAlarm,computer:c.computer,windlass:c.windlass,pilot:c.pilot})[condition]===true;}
export function modelNodes(c){return nodes.map(n=>{
 if(n.id==='electronics'&&c.vhf==='gx2400')return {...n,sub:'GX2400E · dos i40 · ampliacions opcionals',detail:'Ramals protegits per a la GX2400E i la instrumentació SeaTalk. GPS i receptor AIS són interns de la VHF; no necessiten un ramal separat. Les pantalles o equips addicionals només apareixen si els actives.',ports:['+ VHF i retorn − propis','+ instrumentació SeaTalk protegit','ampliacions segons configuració'],source:'gx2400'};
 if(n.id==='navdc'&&c.vhf==='gx2400')return {...n,ports:['ramal VHF protegit + / −','alimentació i40 segons perfil','plotter opcional amb ramal propi']};
 if(n.id==='vhf'&&c.vhf==='gx2400')return {...n,name:'Standard Horizon GX2400E',sub:'GPS + receptor AIS integrats',source:'gx2400',detail:'VHF confirmada amb GPS i receptor AIS integrats. Rebre AIS no fa que el teu vaixell transmeti AIS. No cal afegir GPS de xarxa ni splitter per a aquest receptor. NMEA 2000 i 0183 permeten compartir dades amb equips compatibles; els i40 no mostren AIS.',ports:['12 V DC + / −','antena VHF 50 Ω','GPS intern · sense cable extern obligatori','NMEA 2K · ampliació opcional','NMEA 0183 / HS · alternativa','GND segons manual del fabricant']};
 if(n.id==='i40'&&c.instrument==='BidataWind')return {...n,name:'Raymarine i40 Bidata',sub:'Profunditat i corredera',detail:'Primera pantalla confirmada: i40 Bidata per a profunditat i velocitat per l’aigua. Els dos transductors arriben als seus terminals; SeaTalk comparteix la velocitat amb la pantalla Wind. No és la velocitat GPS sobre el fons.',ports:['SeaTalk 1 · tres contactes','transductor de profunditat','transductor de corredera / temperatura']};
 if(n.id==='transducer'&&c.instrument==='BidataWind')return {...n,name:'Sonda i corredera',sub:'Dos transductors → Bidata'};
 return n;
 });}
export function activeEdges(c,layer){return edges.filter(e=>(!layer||e.layer===layer)&&enabled(e.condition,c)).map(e=>{
 if(e.id==='n6')return {...e,connector:'Spur SeaTalkng–DeviceNet compatible amb el mascle de l’arnès Axiom+; no és un port RayNet'};
 if(e.id==='npower1')return {...e,connector:'Arnès Power / NMEA 2000 Axiom+: vermell + protegit, negre − a SYSTEM MINUS; gris a massa RF o retorn segons manual',protection:'Ramal propi de 12 V; fusible i secció segons mida 7/9/12, llargada i manual. NMEA 2000 no alimenta la pantalla.'};
 if(e.id==='n1'&&c.instrument==='BidataWind')return {...e,label:'Profunditat / corredera',b:'terminals Depth i Speed del Bidata'};
 if(e.id==='r2'&&c.vhf==='gx2400')return {...e,label:'Antena → GX2400E',connector:'Coaxial marí 50 Ω amb PL-259 mascle al cable cap al connector VHF ANT (SO-239) de la GX2400E',protection:'Una antena VHF per a ràdio i receptor AIS intern; no cal splitter extern'};
 return e;
 });}
export function voltageDrop({length,current,area,voltage=12}){if(![length,current,area,voltage].every(Number.isFinite)||length<0||current<0||area<=0||voltage<=0)throw Error('Introdueix valors vàlids: secció i tensió positives; llargada i corrent no negatius.');const drop=2*length*current*.0175/area;return {drop,percent:100*drop/voltage,watts:drop*current};}
export function networkStatus(c){const list=[];if(c.vhf==='gx2400'){list.push('GX2400E: GPS i receptor AIS interns. No és un transceptor AIS.');list.push('Els i40 comparteixen instrumentació per SeaTalk; no visualitzen objectius AIS.');if(!hasNetwork(c))list.push('Perfil bàsic: sense convertidor E22158, backbone NMEA 2000 ni GPS extern.');else list.push('Xarxa opcional: exportació GPS/AIS de la GX2400E i instrumentació dels i40 mitjançant E22158.');}if(c.vhf==='unknown')list.push('Falta el model de VHF: encara no es pot donar per resolta la connexió de dades ni el connector RF.');if(c.ais==='builtin'&&!['ray','gx2400'].includes(c.vhf))list.push('AIS integrat: confirmar que la VHF triada disposa de receptor AIS i sortida de dades.');if(c.vhf==='ray'&&c.ais==='builtin')list.push('En aquest perfil cal una Ray73 per tenir receptor AIS integrat; Ray53 i Ray63 no en tenen.');if(c.vhf==='0183')list.push('Cal configurar la passarel·la amb sortida de posició, sentències acceptades i baud de la VHF.');list.push('L’i40 comparteix instrumentació; no proporciona la posició GPS que necessita DSC.');return list;}

export function powerState(c){return {services:c.main,gasAvailable:c.gasAlarm===true,computer:c.computer===true&&c.main,bilge:c.bilgeMode==='manual'||c.bilgeMode==='auto'&&c.water,charging:[c.engine?'DC–DC':null,c.solar?'MPPT':null,c.shore?'carregador de port':null].filter(Boolean)};}


// Especificació de cada traç funcional. Les seccions no es dedueixen del dibuix.
export function cableSpec(e){
 const ring='Terminal d’anella de coure estanyat crimpat i segellat; barrilet segons mm² i forat segons espàrrec real',borne='Borna del fabricant; puntera si és admesa, secció i parell segons equip',sealed='Arnès original o empalmament crimpat estanc amb termoretràctil adhesiu, fora de l’aigua',factory='Cable original del fabricant; no substituir per una secció genèrica';
 const endpoint=id=>['house','starter','shunt','minus','main','fmain','motor','windlass'].includes(id)?ring:['bilge','lights','cabin','fridge','water','gasProbe'].includes(id)?sealed:borne;
 let type='Coure estanyat multibrins, flexible, d’ús marí; aïllament adequat a temperatura, oli i humitat del recorregut',size='Secció pendent de llargada, corrent, ampacitat, agrupament i protecció; no és una mida de compra validada',connectorA=endpoint(e.from),connectorB=endpoint(e.to);
 if(e.layer==='ac'&&e.type!=='charge'){type=e.type==='earth'?'Conductor flexible verd/groc de protecció; continuïtat PE, mai retorn DC':'Cable flexible marí AC: L marró, N blau i PE verd/groc; PE separat si el traç el representa a part';}
 if(e.type==='solar'){type='Cable fotovoltaic flexible resistent a UV i intempèrie; tensió assignada superior a Voc màxima del conjunt';connectorA='Connector PV de la mateixa família i fabricant als dos costats; contacte i junta segons diàmetre del cable';connectorB=borne;}
 if(e.type==='rf'){type='Coaxial marí de 50 Ω; model i diàmetre segons atenuació, llargada i connector, no segons AWG';size='50 Ω; RG-58 / RG-213 o equivalent només després de verificar pèrdues i radi de curvatura';connectorA=e.a;connectorB=e.b;}
 if(e.type==='sensor'){type='Arnès de transductor específic, amb apantallament si correspon; sense derivacions en paral·lel';size=factory;connectorA=e.a;connectorB=e.b;}
 if(e.type==='gnss'){type=e.cable;size=factory;connectorA=e.a;connectorB=e.b;}
 if(e.type==='network'){type='Cable de xarxa premuntat certificat SeaTalkng / NMEA 2000 segons tram; no cable elèctric genèric';size='Calibre intern del cable homologat; triar llargada, tronc blau o derivació blanca i càrrega LEN';connectorA=e.a;connectorB=e.b;}
 if(e.type==='seatalk'){type='SeaTalk 1 original: positiu, dades i negatiu; tres conductors, no SeaTalkng';size=factory;connectorA=e.a;connectorB=e.b;}
 if(e.type==='nmea0183'){type='Parell trenat apantallat per NMEA 0183, segons interfície del fabricant';size=factory;connectorA=e.a;connectorB=e.b;}
 if(e.type==='usbdata'){type='Cable USB de dades i alimentació conforme a la versió i als ports dels dos equips';size=factory;connectorA=e.a;connectorB=e.b;}
 if(e.type==='fivevolt'){type=e.cable;size=factory;connectorA=e.a;connectorB=e.b;}
 if(['dsense','n8','st-feed','st-supply'].includes(e.id)){type=e.cable;size=factory;connectorA=e.a;connectorB=e.b;}
 if(e.type==='isolation'){type='No aplicable: acoblament magnètic, no hi ha cable ni connector entre bobinats';size='No aplicable: acoblament magnètic, no hi ha cable ni connector entre bobinats';connectorA='No aplicable: acoblament magnètic, no hi ha cable ni connector entre bobinats';connectorB='No aplicable: acoblament magnètic, no hi ha cable ni connector entre bobinats';}
 return {type,size,connectorA,connectorB};
}
export function minimumSection({length,current,voltage=12,percent=3}){
 if(![length,current,voltage,percent].every(Number.isFinite)||length<0||current<0||voltage<=0||percent<=0||percent>100)throw Error('Introdueix valors vàlids: secció i tensió positives; llargada i corrent no negatius.');
 const minimum=2*length*current*.0175/(voltage*percent/100),sizes=[.5,.75,1,1.5,2.5,4,6,10,16,25,35,50,70,95,120,150,185,240];
 return {minimum,standard:sizes.find(s=>s>=minimum)??null};
}
